<template><div><div class="page-title"><div><p class="eyebrow">OVERVIEW</p><h1>欢迎回来</h1><p>店面、订单和菜单管理。</p></div><el-button type="primary" @click="createDialog=true">＋ 创建店面</el-button></div><div class="overview-cards"><router-link to="/admin/orders"><span>🔔</span><h2>订单管理</h2><p>查看和更新当前店面的订单</p><el-tag v-if="newCount" type="danger">{{newCount}} 个新订单</el-tag></router-link><router-link to="/admin/products"><span>🍜</span><h2>菜单管理</h2><p>管理当前店面的菜品与价格</p></router-link><router-link to="/admin/store"><span>🏮</span><h2>店面管理</h2><p>编辑信息或切换店面</p></router-link></div><div class="dashboard-stats"><div><span>今日订单</span><strong>{{todayOrders.length}}</strong></div><div><span>待处理</span><strong>{{newCount}}</strong></div><div><span>今日订单金额</span><strong>¥{{todayRevenue.toLocaleString()}}</strong></div></div><div class="dashboard-orders"><div class="section-heading"><h2>最近订单 · {{activeStore?.name||'当前店面'}}</h2><router-link to="/admin/orders">查看全部 →</router-link></div><el-empty v-if="!orders.length" description="当前店面还没有订单"/><el-table v-else :data="orders.slice(0,8)" stripe><el-table-column prop="id" label="订单编号" min-width="185"/><el-table-column prop="tableNo" label="桌号" width="80"/><el-table-column label="菜品明细" min-width="220"><template #default="s">{{s.row.items.map((item:any)=>`${item.name} × ${item.quantity}`).join('、')}}</template></el-table-column><el-table-column label="总价" width="110"><template #default="s">¥{{s.row.total.toLocaleString()}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="statusType(s.row.status)">{{statusLabel(s.row.status)}}</el-tag></template></el-table-column></el-table></div><el-dialog v-model="createDialog" title="创建店面" width="min(520px, 92vw)"><el-form :model="form" label-position="top"><el-form-item label="店面名称" required><el-input v-model="form.name" maxlength="80" placeholder="例如：Toshio 新宿店"/></el-form-item><el-form-item label="欢迎语"><el-input v-model="form.tagline" maxlength="120"/></el-form-item><el-form-item label="店面公告"><el-input v-model="form.announcement" maxlength="240"/></el-form-item></el-form><template #footer><el-button @click="createDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="createStore">创建</el-button></template></el-dialog></div></template>
<script setup lang="ts">import {computed,ref,onMounted,onUnmounted,watch,reactive} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {api,type Order} from '../api';import {stores,activeStoreId,loadStores,selectStore} from '../storeContext';const router=useRouter(),orders=ref<Order[]>([]),newCount=computed(()=>orders.value.filter(o=>o.status==='new').length),activeStore=computed(()=>stores.value.find(s=>s.id===activeStoreId.value)),today=new Date().toDateString(),todayOrders=computed(()=>orders.value.filter(o=>new Date(o.createdAt).toDateString()===today)),todayRevenue=computed(()=>todayOrders.value.filter(o=>o.status!=='cancelled').reduce((sum,o)=>sum+o.total,0)),createDialog=ref(false),saving=ref(false),form=reactive({name:'',tagline:'',announcement:''});async function load(){try{orders.value=(await api.get('/orders',{params:{storeId:activeStoreId.value}})).data.data}catch{}}async function createStore(){if(!form.name.trim()){ElMessage.error('请填写店面名称');return}saving.value=true;try{const s=(await api.post('/stores',{...form,isOpen:true,address:'',phone:''})).data.data;await loadStores();selectStore(s.id);createDialog.value=false;ElMessage.success('店面已创建');router.push('/admin/store')}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}}function statusLabel(status:string){return({new:'新订单',preparing:'制作中',completed:'已完成',cancelled:'已取消'} as Record<string,string>)[status]||status}function statusType(status:string){return status==='new'?'danger':status==='completed'?'success':status==='cancelled'?'info':'warning'}let timer:number;onMounted(async()=>{try{await loadStores()}catch{}load();timer=window.setInterval(load,5000)});watch(activeStoreId,load);onUnmounted(()=>clearInterval(timer));</script>
